import React, { useState } from 'react';
import './EditPetForm.css';

const EditPetForm = ({ permit, onSave, onCancel }) => {
    const [location, setLocation] = useState(permit.location);
    const [description, setDescription] = useState(permit.description);
    const [duration, setDuration] = useState(permit.duration);
    const [price, setPrice] = useState(permit.price);
    const [errors, setErrors] = useState({});

    const validateInputs = () => {
        const newErrors = {};

        if (!location) {
            newErrors.name = "Name cannot be empty.";
        } else if (/\d/.test(location)) {
            newErrors.name = "Name cannot contain numbers.";
        }

        if (!description) {
            newErrors.description = "Description cannot be empty.";
        }

        if (duration < 0.1 || duration > 100) {
            newErrors.age = "Age must be between 0.1 and 100 years.";
        }

        if (price < 0 || price > 10000) {
            newErrors.price = "Price must be between 0 and 10,000.";
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleSave = () => {
        if (validateInputs()) {
            const updatedPet = {
                ...permit,
                name: location,
                description,
                duration: parseFloat(duration),
                price: parseFloat(price)
            };
            onSave(updatedPet);
        }
    };

    return (
        <div className="edit-pet-form">
            <h2>Edit {permit.name}</h2>
            <label>
                Name:
                <input
                    type="text"
                    value={location}
                    onChange={(e) => setLocation(e.target.value)}
                />
                {errors.name && <span className="error">{errors.name}</span>}
            </label>
            <label>
                Description:
                <input
                    type="text"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                />
                {errors.description && <span className="error">{errors.description}</span>}
            </label>
            <label>
                Age:
                <input
                    type="number"
                    value={duration}
                    onChange={(e) => setDuration(e.target.value)}
                    min="0.1"
                    max="100"
                />
                {errors.age && <span className="error">{errors.age}</span>}
            </label>
            <label>
                Price:
                <input
                    type="number"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    min="0"
                    max="10000"
                />
                {errors.price && <span className="error">{errors.price}</span>}
            </label>
            <div className="form-buttons">
                <button onClick={handleSave}>Save</button>
                <button onClick={onCancel}>Cancel</button>
            </div>
        </div>
    );
};

export default EditPetForm;
